/* Constructed direct gates and actual BerryPhase controls, separate from whole turns. */
#include "pr/engine.h"
#include <stdio.h>
#include <string.h>
static pr_battle bt;static pr_engine e;
int main(int argc,char **argv){if(argc!=2)return 2;FILE *f=fopen(argv[1],"r");char l[256];if(!f||!fgets(l,sizeof l,f)||strcmp(l,"CHEEK_POUCH_HELPERS 1 9\n"))return 2;int failures=0;for(int i=0;i<9;i++){int id,max,hp,eaten,sup,pass,unn,after,ae,stock,count,sum;char extra;
if(!fgets(l,sizeof l,f)||sscanf(l,"H %d %d %d %d %d %d %d %d %d %d %d %d %c",&id,&max,&hp,&eaten,&sup,&pass,&unn,&after,&ae,&stock,&count,&sum,&extra)!=12||id!=i||max<1||max>1000||hp<0||hp>max||after<0||after>max||eaten<0||eaten>1||sup<0||sup>1||pass<0||pass>1||unn<0||unn>1||ae<0||ae>1||stock<0||stock>1||count<0||count>2||sum<0||sum>max)return 2;
memset(&bt,0,sizeof bt);memset(&e,0,sizeof e);pr_pokemon h={0},v={0};h.id=1;h.species=SPECIES_ID_RATTATA;h.is_player=true;h.on_field=true;h.hp=hp;h.stats[0]=max;h.stats[5]=40;h.ability=h.ability_override=pass?ABILITY_ID_BALL_FETCH:ABILITY_ID_CHEEK_POUCH;h.passive=pass?ABILITY_ID_CHEEK_POUCH:0;h.ability_suppressed=sup;h.has_eaten_berry=eaten;v=h;v.id=2;v.is_player=false;v.passive=0;v.hp=v.stats[0]=100;v.stats[5]=20;v.ability=v.ability_override=unn?ABILITY_ID_UNNERVE:ABILITY_ID_BALL_FETCH;v.has_eaten_berry=false;v.ability_suppressed=false;bt.field[0]=&h;bt.field[2]=&v;bt.party[0][0]=&h;bt.party[1][0]=&v;bt.n_party[0]=bt.n_party[1]=1;bt.engine=&e;e.current=-1;
if(i>=3){bt.mods[0][0]=(pr_modifier){.cls=PR_MOD_BERRY,.pokemon_id=1,.stack_count=1,.berry_type=BERRY_TYPE_SITRUS};bt.n_mods[0]=1;int ph=pr_phase_new(&e,PH_BERRY,-1);pr_phase_run(&bt,&e,ph);}else{pr_ab_params p={.pokemon=&h,.move=-1,.simulated=i==1};pr_apply_ab_attrs(&bt,PR_AC_HealFromBerryUseAbAttr,&p);}
int got=0,total=0;for(int k=0;k<PR_MAX_PHASES;k++)if(e.used[k]&&e.pool[k].type==PH_POKEMON_HEAL){got++;total+=e.pool[k].heal_hp;}int stacks=0;for(int j=0;j<bt.n_mods[0];j++)stacks+=bt.mods[0][j].stack_count;if(h.hp!=after||h.has_eaten_berry!=ae||stacks!=stock||got!=count||total!=sum){printf("Cheek helper%d hp%d/%d flag%d/%d stock%d/%d heals%d/%d sum%d/%d\n",i,(int)h.hp,after,h.has_eaten_berry,ae,stacks,stock,got,count,total,sum);failures++;}}
if(!fgets(l,sizeof l,f)||strcmp(l,"END 9\n")||fgetc(f)!=EOF)return 2;printf("Cheek Pouch helpers9 identical%d failures%d\n",9-failures,failures);return failures?1:0;}
